import{U as e,W as t,nt as n,t as r}from"./chunks/framework.BPwQCpO3.js";var i=JSON.parse(`{"title":"测试与验收体系","description":"","frontmatter":{"title":"测试与验收体系"},"headers":[],"relativePath":"zh/guide/testing.md","filePath":"zh/guide/testing.md","lastUpdated":0}`),a={name:`zh/guide/testing.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="_16-测试与验收体系" tabindex="-1">16. 测试与验收体系 <a class="header-anchor" href="#_16-测试与验收体系" aria-label="Permalink to “16. 测试与验收体系”">​</a></h1><h2 id="_16-1-单元测试" tabindex="-1">16.1 单元测试 <a class="header-anchor" href="#_16-1-单元测试" aria-label="Permalink to “16.1 单元测试”">​</a></h2><p>必须覆盖：</p><ul><li>状态转换。</li><li>依赖判定。</li><li>依赖图循环检测。</li><li>AlternativeGroup 判定。</li><li>故障阈值。</li><li>恢复预算。</li><li>候选方案排序。</li><li>通知规则。</li><li>事件去重。</li><li>敏感信息脱敏。</li></ul><h2 id="_16-2-集成测试" tabindex="-1">16.2 集成测试 <a class="header-anchor" href="#_16-2-集成测试" aria-label="Permalink to “16.2 集成测试”">​</a></h2><p>必须覆盖：</p><ul><li>Process Probe。</li><li>Exec Probe。</li><li>插件启动失败。</li><li>插件输出阻塞。</li><li>插件超时。</li><li>插件崩溃。</li><li>资源依赖恢复。</li><li>多个上层资源共同依赖一个资源。</li><li>同一资源并发恢复。</li><li>通知队列持久化。</li><li>数据库重启恢复。</li><li>Dashboard 默认关闭。</li></ul><h2 id="_16-3-故障注入测试" tabindex="-1">16.3 故障注入测试 <a class="header-anchor" href="#_16-3-故障注入测试" aria-label="Permalink to “16.3 故障注入测试”">​</a></h2><p>必须模拟：</p><ol><li>恢复动作执行前进程崩溃。</li><li>恢复动作执行期间进程崩溃。</li><li>恢复动作完成但记录前崩溃。</li><li>动作执行成功但健康验证失败。</li><li>依赖在恢复过程中再次故障。</li><li>插件在请求中途退出。</li><li>通知发送时网络中断。</li><li>SQLite 写入失败。</li><li>多个任务同时要求恢复同一资源。</li><li>达到恢复预算上限。</li></ol><p>每种故障都必须有明确的预期状态和验证断言。</p><h2 id="_16-4-完成定义" tabindex="-1">16.4 完成定义 <a class="header-anchor" href="#_16-4-完成定义" aria-label="Permalink to “16.4 完成定义”">​</a></h2><p>一个阶段只有满足以下条件才算完成：</p><ul><li>代码可编译。</li><li>格式化检查通过。</li><li>静态检查通过。</li><li>单元测试通过。</li><li>集成测试通过。</li><li>关键失败路径有测试。</li><li>文档与实际实现一致。</li><li>不存在未解释的 TODO 或虚假的能力声明。</li><li>失败时不会无限循环。</li><li>所有恢复动作都有明确结果。</li><li>关键状态变化可审计。</li></ul><hr>`,15)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};